   307  M3Result  ParseSection_Code  (M3Module * io_module, bytes_t i_bytes, cbytes_t i_end)
   308  {
   309      M3Result result;
   310
   311      u32 numFunctions;
   312  _   (ReadLEB_u32 (& numFunctions, & i_bytes, i_end));                               m3log (parse, "** Code [%d]", numFunctions);
   313
   314      if (numFunctions != io_module->numFunctions - io_module->numImports)
   315      {
   316          _throw ("mismatched function count in code section");
   317      }
   318
   319      for (u32 f = 0; f < numFunctions; ++f)
   320      {
   321          const u8 * start = i_bytes;
   322
   323          u32 size;
   324  _       (ReadLEB_u32 (& size, & i_bytes, i_end));
   325
   326          if (size)
   327          {
   328              const u8 * ptr = i_bytes;
   329              i_bytes += size;
   330
   331              if (i_bytes <= i_end)
   332              {
   333                  u32 numLocalBlocks;
   334  _               (ReadLEB_u32 (& numLocalBlocks, & ptr, i_end));                                      m3log (parse, "    code size: %-4d", size);
   335
   336                  u32 numLocals = 0;
   337
   338                  for (u32 l = 0; l < numLocalBlocks; ++l)
   339                  {
   340                      u32 varCount;
   341                      i8 wasmType;
   342                      u8 normalType;
   343
   344  _                   (ReadLEB_u32 (& varCount, & ptr, i_end));
   345  _                   (ReadLEB_i7 (& wasmType, & ptr, i_end));
   346  _                   (NormalizeType (& normalType, wasmType));
   347
   348                      numLocals += varCount;                                                      m3log (parse, "      %2d locals; type: '%s'", varCount, c_waTypes [normalType]);
   349                  }
   350
   351                  IM3Function func = Module_GetFunction (io_module, f + io_module->numImports);
   352
   353                  func->module = io_module;
   354                  func->wasm = start;
   355                  func->wasmEnd = i_bytes;
   356                  //func->ownsWasmCode = io_module->hasWasmCodeCopy;
   357                  func->numLocals = numLocals;
   358              }
   359              else _throw (m3Err_wasmSectionOverrun);
   360          }
   361      }
   362
   363      _catch:
   364
   365      if (not result and i_bytes != i_end)
   366          result = m3Err_wasmSectionUnderrun;
   367
   368      return result;
   369  }
